const canvas = document.getElementById('pendulum');
const ctx = canvas.getContext('2d');
const initialAngle = document.getElementById('initial-angle');
const releaseButton = document.getElementById('release-button');
let isReleased = false;
let angle = 0;
let velocity = 0;

function drawPENDULUM() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, 50, 0, 2 * Math.PI);
  ctx.fillStyle = 'blue';
  ctx.fill();

  if (isReleased) {
    angle += velocity;
    velocity -= 9.8 * Math.sin(Math.PI / 180 * angle) / 100; // gravity, convert to radians
    angle %= 360; // keep angle within 0-360 range
  }

  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, 50, Math.PI / 180 * angle, Math.PI / 180 * (angle + 0.1));
  ctx.fillStyle = 'blue';
  ctx.fill();
}

function releasePENDULUM() {
  isReleased = true;
}

releaseButton.addEventListener('click', releasePENDULUM);

function updatePENDULUM() {
  drawPENDULUM();
  requestAnimationFrame(updatePENDULUM);
}

updatePENDULUM();
```
